<?php
declare(strict_types=1);
function rx_panel_capacity(PDO $pdo,array $panel):array{$raw=strtolower(trim((string)($panel['limit_panel']??'')));if(in_array($raw,['','0','-1','unlimited','unlimted','نامحدود','none','null'],true))return['limited'=>false,'reached'=>false,'limit'=>null,'used'=>0];if(!ctype_digit($raw)||(int)$raw<=0){error_log('[panel-capacity] invalid limit treated unlimited panel='.(string)($panel['name_panel']??''));return['limited'=>false,'reached'=>false,'limit'=>null,'used'=>0];}$limit=(int)$raw;$location=trim((string)($panel['name_panel']??''));if($location==='')return['limited'=>false,'reached'=>false,'limit'=>$limit,'used'=>0];$s=$pdo->prepare("SELECT COUNT(*) FROM invoice WHERE Service_location=? AND LOWER(TRIM(status)) IN ('active','sendedwarn','send_on_hold')");$s->execute([$location]);$used=(int)$s->fetchColumn();$s->closeCursor();return['limited'=>true,'reached'=>$used>=$limit,'limit'=>$limit,'used'=>$used,'remaining'=>max(0,$limit-$used)];}
function rx_panel_capacity_log(array $panel,array $capacity,string $context=''):void{if(empty($capacity['reached']))return;error_log('[panel-capacity] reached context='.$context.' panel='.(string)($panel['name_panel']??'').' used='.(string)($capacity['used']??0).' limit='.(string)($capacity['limit']??0));}
